const b = $json.body || $json;
const text = String(b.text || '').toLowerCase();
const from = String(b.from || '').trim();
const faqs = b.faqs || {
  horario: 'Atendemos lun–vie 9 a 18 hs.',
  precio: 'Te paso la lista de precios por este chat.',
  direccion: 'Estamos en el centro — pedime el mapa si querés.',
  servicios: 'Contame qué necesitás y te digo si lo cubrimos.'
};
let key = 'servicios';
let reply = faqs.servicios;
for (const k of Object.keys(faqs)) {
  if (text.includes(k) || (k === 'direccion' && (text.includes('dirección') || text.includes('donde')))) {
    key = k; reply = faqs[k]; break;
  }
}
return [{ json: {
  ok: true,
  sistema: '09-wasap-task-faq-citas',
  etapa: 'faq',
  from, key, reply,
  status: 'draft_ready',
  todo: 'TODO_CREDENCIAL: send Wasap + faq por cliente',
  at: new Date().toISOString()
}}];
